// The sky behind everything: a field of stars on the fixed canvas the layout
// puts at the back, drifting, twinkling on their own clocks, leaning with the
// mouse, and every so often a shooting star.
//
// Filename note: this is not minified and has not been for a while — it is
// hand-written like the rest of source/js, and the name only survives because
// layout.ejs asks for this path.
//
// The stars are in the site's own colours: the two stops of the #menu gradient,
// the blend between them so the field has a middle note, and the teal the post
// titles are set in. Nothing here invents a colour.

(function () {
    const canvas = document.getElementById("background");
    if (!canvas) return;

    const ctx = canvas.getContext("2d");

    // #menu's gradient runs #e4c6d0 -> #cca4e3; the third entry is where it is
    // halfway along. The last is #85bac0, which is what .post-title is set in.
    const COLOURS = [
        [228, 198, 208],
        [216, 181, 218],
        [204, 164, 227],
        [133, 186, 192],
    ];

    // One star per this many CSS pixels of viewport, so a phone gets a thinner
    // sky than a desktop does, with a floor so it never looks bare.
    const PIXELS_PER_STAR = 13000;
    const MIN_STARS = 30;

    // The core, in CSS pixels. The spread is squared rather than even, which
    // puts most of the field near the small end and leaves the large size for
    // the few stars that should carry it — an even spread over this range reads
    // as a field of dots all the same weight.
    const RADIUS_MIN = 0.7;
    const RADIUS_MAX = 2.2;
    const RADIUS_SKEW = 2;
    // The glow, as a multiple of the core's radius and a fraction of the star's
    // alpha. Wide and faint, stamped from a pre-rendered falloff rather than
    // filled as a circle — a filled circle has an edge no matter how faint, and
    // at this size an edge reads as a plate the star is sitting on.
    // The alpha here is the sprite's own falloff times the star's, and the
    // falloff spends most of its radius well under its centre value, so this
    // number has to be generous for the glow to read at all. It is not what
    // makes the glow soft — the falloff is.
    const HALO_SCALE = 6;
    const HALO_ALPHA = 0.32;
    const HALO_SPRITE = 64;

    // Twinkle: the alpha swings between these and turns around at each end.
    // It never reaches nothing — a star that blinks out reads as a dropped
    // frame — and the top of the swing is deliberately short of full, so that
    // even at its brightest a star is a suggestion rather than something to
    // point at.
    //
    // The floor is set against a light page rather than a dark one. Every
    // colour in the palette is a pastel, and the page is #f6f8fa, so a star at
    // 0.1 alpha is not a dim star here, it is no star at all.
    const TWINKLE_MIN = 0.2;
    const TWINKLE_MAX = 0.62;
    // How fast a star goes round. A cycle is twice the swing's range divided by
    // this, so with the range at 0.42 the two ends are about two and a half
    // seconds a cycle and about eleven — the same spread of periods the swing
    // had before it was shortened, which is what these two numbers are here to
    // hold. Shorten the swing further and they have to come down with it, or the
    // stars speed up.
    const TWINKLE_STEP_MIN = 0.002;
    const TWINKLE_STEP_MAX = 0.007;

    // Each star's own motion, in CSS pixels per frame: enough to keep the field
    // alive when nothing else is happening, not enough to watch.
    const DRIFT_X = 0.06;
    const DRIFT_Y = 0.03;

    // The mouse. A movement pushes a camera, and the stars follow it by their
    // own depth, so nearer ones travel further and the field has some give to
    // it. PUSH is how much of the movement reaches the camera, DECAY is how
    // quickly the push fades once the pointer stops, and FOLLOW is how fast the
    // camera catches up with the push it was given.
    //
    // The push decays rather than stopping, so the field keeps travelling for a
    // while after the pointer does and the movement it ends up covering is
    // PUSH / (1 - PUSH_DECAY) times the pointer's own — at 0.125 that was two
    // and a half times over, which reads as the sky being dragged.
    //
    // This is the knob for how fast the field moves, and it is the only one.
    // Slowing the decay or the chase changes the shape of the movement, not its
    // speed: the distance and the time stretch together, so the field still
    // crosses the same ground at the same rate, just more gradually. Only the
    // push itself sets the speed — and it sets the distance with it, which is
    // why weakening the follow shortens it as well as slowing it.
    const PUSH = 0.006;
    const PUSH_DECAY = 0.95;
    // And how sharply it takes up the push. Low enough that the field leans
    // into a movement rather than snapping after it.
    const FOLLOW = 0.3;

    // There is no trail behind the stars. One was tried at several lengths and
    // widths and taken out again: at every size it read as a mark drawn on the
    // field rather than as the field moving, which is the whole thing the field
    // is not supposed to be. A star is a point of light; the pointer moves it.

    // Shooting stars: how long to wait between them, how many can be in the air
    // at once, and how fast and how long they are. The gaps are deliberately
    // long. This is a background — a streak every second is something to watch
    // rather than something to read past, which is the opposite of the point.
    const SHOOTING_GAP_MIN = 3500;
    const SHOOTING_GAP_MAX = 9000;
    const SHOOTING_MAX = 2;
    const SHOOTING_SPEED_MIN = 4.5;
    const SHOOTING_SPEED_MAX = 8;
    const SHOOTING_LENGTH_MIN = 70;
    const SHOOTING_LENGTH_MAX = 150;
    // The palette mixed towards white for these. A shooting star is already the
    // brightest thing on the screen by virtue of moving, and the palette at full
    // strength made it an event rather than a passing one.
    const SHOOTING_LIGHTEN = 0.3;

    let width = 0;
    let height = 0;
    let stars = [];
    let shooting = [];
    let shootingIn = SHOOTING_GAP_MIN;

    // `x`/`y` are where the camera is, `tx`/`ty` the push it has been given.
    // The push decays towards nothing and the camera chases it, so a flick of
    // the mouse moves the field and then leaves it still.
    const camera = { x: 0, y: 0, tx: 0, ty: 0 };
    let lastX = null;
    let lastY = null;

    // The field moves on its own clock, so the constants above are per 60Hz
    // frame and the frame's own length scales them. Without this a twinkle that
    // takes five seconds on one screen takes two and a half on a 120Hz one.
    let lastFrame = 0;

    // One falloff per palette colour, drawn once and stamped under every star of
    // that colour. Building these per star per frame would mean a new gradient
    // 60 times a second for each of them, which is a lot of gradients to make a
    // background look soft.
    const halos = COLOURS.map(([r, g, b]) => {
        const sprite = document.createElement("canvas");
        sprite.width = sprite.height = HALO_SPRITE;
        const spriteCtx = sprite.getContext("2d");
        const half = HALO_SPRITE / 2;
        const falloff = spriteCtx.createRadialGradient(half, half, 0, half, half, half);
        falloff.addColorStop(0, `rgba(${r}, ${g}, ${b}, 1)`);
        falloff.addColorStop(0.3, `rgba(${r}, ${g}, ${b}, 0.42)`);
        falloff.addColorStop(0.65, `rgba(${r}, ${g}, ${b}, 0.1)`);
        falloff.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0)`);
        spriteCtx.fillStyle = falloff;
        spriteCtx.fillRect(0, 0, HALO_SPRITE, HALO_SPRITE);
        return sprite;
    });

    function lighten(colour) {
        return colour.map((channel) =>
            Math.round(channel + (255 - channel) * SHOOTING_LIGHTEN)
        );
    }

    function createStar() {
        const colour = (Math.random() * COLOURS.length) | 0;
        return {
            x: Math.random() * width,
            y: Math.random() * height,
            radius:
                RADIUS_MIN +
                Math.pow(Math.random(), RADIUS_SKEW) *
                    (RADIUS_MAX - RADIUS_MIN),
            // How far this star travels with the camera. The range is narrow on
            // purpose: too much and the field reads as layers, too little and
            // the mouse might as well be moving nothing.
            depth: 0.35 + Math.random() * 0.65,
            colour: COLOURS[colour],
            halo: halos[colour],
            alpha: Math.random(),
            step:
                (TWINKLE_STEP_MIN +
                    Math.random() * (TWINKLE_STEP_MAX - TWINKLE_STEP_MIN)) *
                (Math.random() < 0.5 ? -1 : 1),
            driftX: (Math.random() - 0.5) * DRIFT_X * 2,
            driftY: (Math.random() - 0.5) * DRIFT_Y * 2,
        };
    }

    // Every one of them runs the same way: down and to the left, at the shallow
    // angles a meteor actually crosses a sky, starting in the upper right so it
    // arrives rather than appears.
    //
    // One direction rather than both, because a shower has a radiant — its
    // meteors run roughly parallel — and meteors crossing each other read as a
    // wall of streaks rather than as a sky with something moving through it.
    function createShootingStar() {
        const angle = (Math.PI * 5) / 6 - Math.random() * (Math.PI / 6);
        return {
            x: width * (0.4 + Math.random() * 0.6),
            y: Math.random() * height * 0.5,
            angle,
            speed:
                SHOOTING_SPEED_MIN +
                Math.random() * (SHOOTING_SPEED_MAX - SHOOTING_SPEED_MIN),
            length:
                SHOOTING_LENGTH_MIN +
                Math.random() * (SHOOTING_LENGTH_MAX - SHOOTING_LENGTH_MIN),
            colour: lighten(COLOURS[(Math.random() * COLOURS.length) | 0]),
            alpha: 1,
            // Fading is what ends one: it takes the tail with it, so a shooting
            // star leaves nothing behind to be cleared up.
            decay: 0.008 + Math.random() * 0.01,
        };
    }

    function resize() {
        const ratio = window.devicePixelRatio || 1;
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = width * ratio;
        canvas.height = height * ratio;
        // Draw in CSS pixels; the ratio is carried by the transform, so the
        // backing store is scaled and the stars stay crisp on a dense display.
        ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
        const count = Math.max(
            MIN_STARS,
            Math.round((width * height) / PIXELS_PER_STAR)
        );
        stars = [];
        for (let i = 0; i < count; i++) stars.push(createStar());
    }

    function drawStar(star, scale) {
        star.alpha += star.step * scale;
        if (star.alpha >= TWINKLE_MAX) {
            star.alpha = TWINKLE_MAX;
            star.step = -star.step;
        } else if (star.alpha <= TWINKLE_MIN) {
            star.alpha = TWINKLE_MIN;
            star.step = -star.step;
        }

        star.x += camera.x * star.depth + star.driftX * scale;
        star.y += camera.y * star.depth + star.driftY * scale;
        // Wrapped rather than recycled: the field has no edges and no direction
        // for a star to be lost in.
        if (star.x < -5) star.x = width + 5;
        else if (star.x > width + 5) star.x = -5;
        if (star.y < -5) star.y = height + 5;
        else if (star.y > height + 5) star.y = -5;

        const [r, g, b] = star.colour;

        const halo = star.radius * HALO_SCALE;
        ctx.globalAlpha = star.alpha * HALO_ALPHA;
        ctx.drawImage(star.halo, star.x - halo, star.y - halo, halo * 2, halo * 2);
        ctx.globalAlpha = 1;

        ctx.beginPath();
        ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${star.alpha})`;
        ctx.fill();
    }

    function drawShootingStar(star, scale) {
        star.x += Math.cos(star.angle) * star.speed * scale;
        star.y += Math.sin(star.angle) * star.speed * scale;
        star.alpha -= star.decay * scale;
        if (
            star.alpha <= 0 ||
            star.x < -star.length ||
            star.x > width + star.length ||
            star.y > height + star.length
        ) {
            return false;
        }

        const [r, g, b] = star.colour;
        const tailX = star.x - Math.cos(star.angle) * star.length;
        const tailY = star.y - Math.sin(star.angle) * star.length;
        // The tail is the head's colour with the alpha run out of it, so the
        // streak reads as something travelling rather than as a drawn line.
        const tail = ctx.createLinearGradient(star.x, star.y, tailX, tailY);
        tail.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${star.alpha})`);
        tail.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0)`);
        ctx.strokeStyle = tail;
        ctx.lineWidth = 2;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(star.x, star.y);
        ctx.lineTo(tailX, tailY);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(star.x, star.y, 1.6, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${star.alpha})`;
        ctx.fill();
        return true;
    }

    function draw(now) {
        const delta = lastFrame ? Math.min(now - lastFrame, 100) : 1000 / 60;
        lastFrame = now;
        const scale = delta / (1000 / 60);

        ctx.clearRect(0, 0, width, height);

        camera.tx *= PUSH_DECAY;
        camera.ty *= PUSH_DECAY;
        camera.x += FOLLOW * (camera.tx - camera.x);
        camera.y += FOLLOW * (camera.ty - camera.y);

        for (const star of stars) drawStar(star, scale);

        shootingIn -= delta;
        if (shootingIn <= 0) {
            shootingIn =
                SHOOTING_GAP_MIN +
                Math.random() * (SHOOTING_GAP_MAX - SHOOTING_GAP_MIN);
            if (shooting.length < SHOOTING_MAX) shooting.push(createShootingStar());
        }
        shooting = shooting.filter((star) => drawShootingStar(star, scale));

        requestAnimationFrame(draw);
    }

    window.addEventListener("resize", resize);
    window.addEventListener("mousemove", (event) => {
        // The first move only plants the pointer: without a previous position
        // there is no movement to measure, and the jump from the origin would
        // fling the field across the screen.
        if (lastX !== null) {
            camera.tx = camera.x + (event.clientX - lastX) * PUSH;
            camera.ty = camera.y + (event.clientY - lastY) * PUSH;
        }
        lastX = event.clientX;
        lastY = event.clientY;
    });
    window.addEventListener("mouseleave", () => {
        lastX = null;
        lastY = null;
    });

    resize();
    requestAnimationFrame(draw);
})();
